tool_input.command:
$env:OV_MAX_COMMIT_QUEUE='64'
$log = Join-Path $env:TEMP 'import-cursor-backfill.log'
$utf8 = New-Object System.Text.UTF8Encoding $false
function Log($s) { [IO.File]::AppendAllText($log, $s + [Environment]::NewLine, $utf8) }
$root = Join-Path (Get-Location) 'out\distilled-local\cursor'
$projs = @('iHome2.0小程序','d-repository','i淮安公版','苏州市房地产监测V3')
Log "`n======== RESUME AFTER DSH RESTART $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') ========"
$fail = 0
foreach ($p in $projs) {
  Log "`n--- $p ---"
  $src = Join-Path $root $p
  if (-not (Test-Path $src)) { Log 'SKIP: no distill'; continue }
  $done = Join-Path $env:TEMP ("done-ov-cursor-" + $p + '.json')
  $out = & node import-to-ov.mjs $p --batch=4 --gap=8000 --src=$src --done=$done --skip=$done 2>&1 | ForEach-Object { $_.ToString() }
  $out | ForEach-Object { Log $_ }
  if ($LASTEXITCODE -ne 0) { $fail = $LASTEXITCODE }
  Log "exit=$LASTEXITCODE"
}
Log "======== BACKFILL END $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') lastExit=$fail ========"
exit $fail
